**`calc.js`** — reads `numbers.txt`, sums the integers (validating each line, skipping blanks), and prints the total:

```js
const fs = require('fs');

const data = fs.readFileSync('numbers.txt', 'utf8');
let sum = 0;
for (const line of data.split(/\r?\n/)) {
  const trimmed = line.trim();
  if (trimmed === '') continue;
  const num = Number(trimmed);
  if (!Number.isInteger(num)) {
    console.error(`Invalid integer: ${trimmed}`);
    process.exit(1);
  }
  sum += num;
}
console.log(sum);
```

